  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'analytical', 'In recent years, the number of Bhutanese travelling abroad has increased manifold. It is estimated that more than 15,000 Bhutanese are currently abroad, spread over almost all the countries. Some return to Bhutan, while others continue to stay abroad. The number of Bhutanese travelling or living abroad will inevitably increase in the coming years.
Discuss some of the impacts of this scenario on socio-economic development in Bhutan. (20 marks)', 'More and more Bhutanese are going abroad to work and study, particularly to Australia, the Middle East, Japan, the United States and elsewhere.
Positive impacts:
1. Remittances bring in foreign currency, increase household incomes and help families build houses, educate children and start businesses.
2. Going abroad reduces unemployment pressure at home, especially among youth.
3. Returnees bring back skills, work ethic, experience and international exposure.
4. Savings from abroad can be invested in businesses and property in Bhutan.
5. The diaspora builds networks and promotes Bhutan''s image abroad.
Negative impacts:
1. Brain drain: skilled and experienced professionals - doctors, nurses, teachers, engineers and civil servants - leave, weakening public services.
2. Labour shortages in key sectors, increasing reliance on foreign workers.
3. Loss of the public investment made in free education and training.
4. Family separation: children are left with grandparents, marriages are strained, and elderly parents are left alone.
5. Rural depopulation and fallow land increase.
6. Risk of cultural erosion and weaker community ties.
7. Some workers abroad face exploitation, debt and hardship.
8. A shrinking working-age population can slow long-term growth.
Way forward: engage the diaspora through networks and investment opportunities, encourage skilled people to return with attractive careers and pay, regulate overseas employment agencies to protect workers, and create more quality jobs at home. Managed well, migration can become a source of strength rather than loss.', null, '[{"point": "Positive impacts: remittances (foreign exchange, household income, poverty reduction), reduced unemployment pressure, skills, experience and exposure brought back, savings and investment by returnees, networks/ diaspora links, promoting Bhutan abroad", "marks": 8}, {"point": "Negative impacts: brain drain and loss of skilled workers (health, education, civil service), labour shortage, loss of return on public investment in education, family separation and social problems, elderly left alone, rural depopulation, cultural erosion, exploitation/ welfare of workers abroad, demographic decline", "marks": 8}, {"point": "Suggestions: engage diaspora, encourage return and investment, regulated overseas employment, improve jobs and pay at home; conclusion", "marks": 4}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'migration-and-the-diaspora'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 20,
    2160, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (General): BCSE 2021, batch 2", "source": {"title": "BCSE 2021 Main Examination, General category, Paper III", "year": 2021, "url": "https://rcsc.gov.bt/bcse-past-question-papers/"}}'::jsonb, null, null, null, null, null, null)
